def find_o(s):
    if s == 'o':
        return 1
    elif s == 'O':
        return 2
    elif s == 'Oo':
        return 3
    elif s == 'OoO':
        return 4
    elif s == 'OoOo':
        return 5
    elif s == 'OoOoO':
        return 6
    elif s == 'OoOoOo':
        return 7

